What will the output of the following code?

#include <iostream>
using namespace std;
int main() {
    int day = 1;
    switch (day) {
        case 1: cout << "Monday"; break;
        case 2: cout << "Tuesday"; break;
        case 3: cout << "Wednesday"; break;
        default: cout << "Invalid day"; break;
    }
    return 0;
}
